    "Script": "FlowSettings = {
	   init: function (app, container, flow, callback) {
			api.get('AppSecurity/Role?$filter=AppId eq ' + app.Id).then(function(res){
				  FlowSettings.setupRoles(app, container, res.value, flow, callback);
			});
	   },

	   setupRoles: function(app, container, roles, flow, callback){
			var userRoles = roles.map(r => {
				r.CanExecute = flow.Definition.RequiredRoles.indexOf(r.Name) > -1;
                r.CanAdminister = r.Privs.indexOf("flowdefinition_admin") > -1;
				return r;
			});

			$('[name=roles]', container).kendoGrid({
				dataSource:userRoles,
                width: 320,
				columns:[
					{ width: 50, title:' Exec', field: 'CanExecute', template: '<input data-bind="checked: CanExecute" type="checkbox" #:CanExecute ? "checked" : "" # />' },
                    { width: 50, title:'Admin ', field: 'CanAdminister', template: '<input data-bind="checked: CanAdminister" type="checkbox" #:CanAdminister ? "checked" : "" # />' },
					{ field: 'Name' , width: 200}
				]
			});

            $("button[name=save]", container).on("click", function(e) { flow.model.save(); callback(); });
	   }
};
