   JSON.parse('{"ServerTypeName":"MailReceiver","Category":"Mail","Properties":[{"Name":"Id","Type":"guid","Template":"key","IsValueType":true,"ShortDisplayName":"Id"},{"Name":"AppId","Type":"number","IsValueType":true,"ShortDisplayName":"AppId"},{"Name":"Name","Type":"string","IsValueType":true,"ShortDisplayName":"Name"},{"Name":"ProviderName","Type":"string","IsValueType":true,"ShortDisplayName":"ProviderName"},{"Name":"User","Type":"string","IsValueType":true,"ShortDisplayName":"User"},{"Name":"Password","Type":"string","IsValueType":true,"ShortDisplayName":"Password"},{"Name":"Host","Type":"string","IsValueType":true,"ShortDisplayName":"Host"},{"Name":"Port","Type":"number","IsValueType":true,"ShortDisplayName":"Port"},{"Name":"EnableSSL","Type":"bool","IsValueType":true,"ShortDisplayName":"EnableSSL"},{"Name":"LastReceivedOn","Type":"date","IsValueType":true,"ShortDisplayName":"LastReceivedOn"},{"Name":"IsEnabled","Type":"bool","IsValueType":true,"ShortDisplayName":"IsEnabled"}]}')
  );

