   {field:"SentByUserId",title:"Sent by user"},
   {field:"To",title:"To"}
  ],["Subject","SentByUserId","To"]);
  MailManagement.summaryGrid(app,container,"SentEmail","history",[
   {field:"Subject",title:"Subject"},
   {field:"SentOn",title:"Sent on",type:"date",format:"{0: "+type.dateAndTimeFormat + "}"}
  ],["Subject","SentOn"]);
  MailManagement.endpointGrid(app,container,"MailSender","senders",[
   {field:"Name",title:"Name"},{field:"ProviderName",title:"Provider"},{field:"Host",title:"Host"}
