   {field:"Name",title:"Name"},{field:"ProviderName",title:"Provider"},{field:"Host",title:"Host"}
  ],["Id","AppId","Name","ProviderName","User","Password","Host","Port","EnableSSL","LastReceivedOn","IsEnabled"],
  {ProviderName:"",EnableSSL:true,IsEnabled:true});
 },
 summaryGrid: async function(app,container,setName,target,columns,summaryFields) {
  var endpoint="Mail/"+setName;
  var append="?$filter=AppId eq "+app.Id+(setName==="QueuedEmail"?"&$expand=FailedSends":"");
  var source=await model.getDatasource({endpoint:endpoint,odataAppend:append});
  var grid=new GridWidget($("[name="+target+"]",container),source);
  grid.filterable=true; grid.groupable=false; grid.columns=columns;
  grid.detailTemplate="<div name='mailRecordDetails'></div>";
  grid.detailExpand=function(e){
   var item=grid.dataItem(e.masterRow);
   MailManagement.renderMessageDetails($("[name=mailRecordDetails]",e.detailRow),item,summaryFields,setName);
  };
  if(setName==="QueuedEmail"){
   grid.commands.push({name:"destroy",icon:"k-i-trash",text:"delete"});
   grid.dataBound=function(){
    $("[name=destroy]",grid.gridElement).off("click").on("click",async function(e){
     e.preventDefault(); var item=grid.dataItem($(e.currentTarget).closest("tr"));
     await api.destroy(endpoint+"("+item.Id+")"); notification.success("deleted"); grid.refresh();
    });
   };
