  grid.detailExpand=function(e){
   MailManagement.renderEditor($("[name=mailRecordEditor]",e.detailRow),grid.dataItem(e.masterRow),endpoint,detailFields,grid);
  };
  grid.commands.push({name:"remove",icon:"k-i-trash",text:"remove"});
