   $("[name=remove]",grid.gridElement).off("click").on("click",async function(e){
    e.preventDefault(); var item=grid.dataItem($(e.currentTarget).closest("tr"));
    await api.destroy(endpoint+"("+item.Id+")"); notification.success("deleted"); grid.refresh();
   });
   $("button[name=create]",grid.gridElement).off("click").on("click",function(e){
    e.preventDefault();
    var data=Object.assign({Id:"00000000-0000-0000-0000-000000000000",AppId:app.Id,Name:"",User:"",Password:"",Host:"",Port:0},defaults);
    var fields=detailFields.filter(function(x){return x!=="Id"&&x!=="AppId"&&x!=="LastReceivedOn";}).map(function(x){return {field:x,title:MailManagement.label(x)};});
    var dialog=new EditorDialog({fields:fields,title:"Create "+setName.replace("Mail","mail ").toLowerCase(),data:data,confirm:"confirm",close:"close"});
    dialog.events.confirm=async function(){await api.add(endpoint,dialog.data.toJSON());dialog.events.close();notification.success("created");grid.refresh();};
    dialog.init();
   });
