 },
 renderMessageDetails: function(host,item,summaryFields,setName) {
  var id=Guid(),detailsId="mail-details-"+id,previewId="mail-preview-"+id,failuresId="mail-failures-"+id;
  var failuresTab=setName==="QueuedEmail"?"<button class='nav-link' data-bs-toggle='tab' data-bs-target='#"+failuresId+"'>Failed sends</button>":"";
  var failuresPane=setName==="QueuedEmail"?"<div class='tab-pane fade p-3' id='"+failuresId+"'><div name='failures'></div></div>":"";
  host.html("<div class='tab-control'><nav><div class='nav nav-tabs' role='tablist'>"+
   "<button class='nav-link active' data-bs-toggle='tab' data-bs-target='#"+detailsId+"'>Details</button>"+
   "<button class='nav-link' data-bs-toggle='tab' data-bs-target='#"+previewId+"'>Preview</button>"+failuresTab+
   "</div></nav><div class='tab-content'>"+
   "<div class='tab-pane fade show active p-3' id='"+detailsId+"'><dl class='row mb-0' name='fields'></dl></div>"+
   "<div class='tab-pane fade p-3' id='"+previewId+"'><iframe title='Email preview' style='width:100%;min-height:28rem;border:0'></iframe></div>"+failuresPane+
   "</div></div>");
  var fields=api.getType(item.type).Properties.filter(function(x){
   return x.IsValueType&&x.Name!=="Content"&&summaryFields.indexOf(x.Name)<0;
  });
  var list=$("[name=fields]",host);
  fields.forEach(function(field){
   var value=item[field.Name];
   if(value instanceof Date)value=kendo.toString(value,type.dateAndTimeFormat);
   list.append($("<dt class='col-sm-3'></dt>").text(field.ShortDisplayName||MailManagement.label(field.Name)));
   list.append($("<dd class='col-sm-9'></dd>").text(value==null?"":value));
  });
  if(setName==="QueuedEmail"){
   var failures=item.FailedSends||[],table=$("<table class='table table-striped'><thead><tr><th>Attempted on</th><th>Failure reason</th></tr></thead><tbody></tbody></table>");
   failures.forEach(function(failure){
    var attempted=failure.AttemptedOn?kendo.toString(new Date(failure.AttemptedOn),type.dateAndTimeFormat):"";
    var row=$("<tr></tr>"); row.append($("<td></td>").text(attempted)); row.append($("<td></td>").text(failure.FailureReason||"")); $("tbody",table).append(row);
   });
   if(failures.length===0)$("[name=failures]",host).text("No failed sends."); else $("[name=failures]",host).append(table);
  }
  var frame=$("iframe",host)[0],doc=frame.contentDocument||frame.contentWindow.document;
  doc.open(); doc.write(item.Content||""); doc.close();
 },
 renderEditor: function(host,item,endpoint,fields,grid) {
  var form=$("<form class='p-3 mail-record-editor'></form>");
  fields.forEach(function(field){
   var typeInfo=api.getType(item.type).Properties.filter(function(x){return x.Name===field;})[0]||{Type:"string"};
   var readOnly=field==="Id"||field==="AppId"||field==="LastReceivedOn";
   var row=$("<div class='row align-items-center mb-2'></div>");
   row.append($("<label class='col-sm-3 col-form-label'></label>").text(MailManagement.label(field)));
   var value=item[field],input;
   if(typeInfo.Type==="bool"){
    input=$("<input type='checkbox' class='form-check-input' data-field='"+field+"'>").prop("checked",!!value);
   }else{
    input=$("<input class='form-control' data-field='"+field+"'>").val(value==null?"":value);
    if(field==="Password")input.attr("type","password");
    if(typeInfo.Type==="number")input.attr("type","number");
    if(typeInfo.Type==="date")input.attr("type","datetime-local");
   }
   if(readOnly)input.prop("disabled",true);
   row.append($("<div class='col-sm-9'></div>").append(input)); form.append(row);
  });
  form.append("<div class='d-flex justify-content-end pt-2'><button class='btn btn-primary' name='save'><span class='k-icon k-i-save'></span> save</button></div>");
  host.empty().append(form);
  $("button[name=save]",form).on("click",async function(e){
   e.preventDefault();
   $("[data-field]",form).each(function(){
    var input=$(this),field=input.data("field"); if(input.prop("disabled"))return;
    var meta=api.getType(item.type).Properties.filter(function(x){return x.Name===field;})[0]||{Type:"string"};
    var value=meta.Type==="bool"?input.prop("checked"):input.val();
    if(meta.Type==="number")value=parseInt(value)||0;
    item.set(field,value);
   });
   await api.update(endpoint+"("+item.Id+")",item.prepForPush());
   notification.success("saved"); grid.refresh();
  });
 },
 label: function(value) {
  return value.replace(/([a-z0-9])([A-Z])/g,"$1 $2").replace(/^./,function(x){return x.toUpperCase();});
 }
};",
