    "Name": "ClientList",
    "Key": "DocumentManagement",
    "ResourceKey": "DocumentManagement",
    "Script": "ClientList = {
    init: async function (app, container) {
        app = app || session.app;
        container = container || $(".component[name=ClientList]");
        var clientList = [];
        await api.get("DMS/" + app.Config.CRM.ClientFolder + "clientList.json")
            .then((sub) => clientList = sub)
            .catch(async (err) => {
                error(err);
                clientList = [];
                await api.put("DMS/" + app.Config.CRM.ClientFolder + "clientList.json", clientList);
            }).finally(async () => {
                var clientGrid = new GridWidget(container, { data: clientList });
                clientGrid.toolbar = "<button name='add'><span class='k-icon k-i-plus'></span>[resource_displayname[add]]</button>";
                clientGrid.dataBound = function () {
                    $("a[name=view]", clientGrid.gridElement).on("click", (e) => ClientList.viewClient(e, clientGrid, app));
                    $("a[name=remove]", clientGrid.gridElement).on("click", (e) => ClientList.removeClient(e, clientGrid, app, clientList));
                    $("a[name=scanClient]", clientGrid.gridElement).on("click", async (e) => await ClientList.scanClient(e, clientGrid, app, clientList));
                };
                clientGrid.editable = false;
                clientGrid.commands.push({ name: "view", icon: "k-i-share", text:"[resource_displayname[view]]" });
                clientGrid.commands.push({ name: "remove", icon: "k-i-trash", text: "[resource_displayname[remove]]" });
                clientGrid.commands.push({name:"scanClient", icon:"k-i-share", text:"[resource_displayname[scanClient]]"});
                clientGrid.columns = [
                    { field: "name", title: "[resource_shortdisplayname[name]]" },
                    { field: "created", type: "date", format: "{0:" + type.dateFormat + "}", title: "[resource_shortdisplayname[created]]", width: 100 },
                    { field: "lastUpdated", type: "date", format: "{0:" + type.dateFormat + "}", title: "[resource_shortdisplayname[lastupdated]]", width: 100 },
                    { field: "state", title: "[resource_shortdisplayname[state]]" }
                ];
                clientGrid.detailTemplate = "<div name='client'></div>";
                clientGrid.detailExpand = (e) => {
                    var client = clientGrid.dataItem($(e.masterRow));
                    var container = $(e.detailRow).find("div[name=client]");
                    container.html("");
                    loadComponent(container, "ClientState", (c) => {
                        c.init(app, $(".component[name=ClientState]", container), client);
                    });
                }
                await clientGrid.init();
                $("button[name=add]", clientGrid.gridElement).on("click", (e) => ClientList.addClient(container, clientGrid, app));
            });
    },


    addClient: function (container, grid, app) {
        var clientNameDialog = new Dialog({ title: "[resource_displayname[ClientName]]" });
        clientNameDialog.template = $("[name=clientNameDialog]", container).html();
        clientNameDialog.events.confirm = async function () {
            var name = $("[name=clientName]", clientNameDialog.element).val();
            clientNameDialog.events.close();
            var clientList = await api.get("DMS/" + app.Config.CRM.ClientFolder + "clientList.json");
            clientList.push({ 
                name: name, 
                created: (new Date()).toISOString(), 
                state: "Unscanned", 
                details: "crm/clients/" + name, 
                lastUpdated: (new Date()).toISOString()
            });
            await api.put("DMS/" + app.Config.CRM.ClientFolder + "clientList.json", clientList);
            await api.put("DMS/" + app.Config.CRM.ClientFolder + name + "/apps.json",[]);
            await api.put("DMS/" + app.Config.CRM.ClientFolder + name + "/history.json",[]);
            await api.put("DMS/" + app.Config.CRM.ClientFolder + name + "/themes.json",[]);
            grid.kendoObject.setDataSource({ data: clientList });
            grid.refresh();
        };
        clientNameDialog.init();
    },

    viewClient: function (e, grid) {
        var item = grid.dataItem($(e.currentTarget).closest("tr"));
        window.location.href = window.location.protocol + "//" + window.location.hostname + "/Admin/Client?Name=" + item.name;
    },

    scanClient: async function (e, grid, app, clientEntry) {
        var item = grid.dataItem($(e.currentTarget).closest("tr"));
        var scanClientScript = [dms[scripts/crm/scanclient.js]];
        var environmentInfo = JSON.parse(await api.get("DMS/" + JSON.parse(app.ConfigJson).CRM.ClientFolder + "/environments.json")).CurrentEnvironment;
        var appId = item.apps.filter(r=>r.environment == environmentInfo)[0].appId;
        clientEntry.state = await scanClientScript(appId);
        await api.put("DMS/" + app.Config.CRM.ClientFolder + "clientList.json",clientList);
    },

    removeClient: async function (e, grid, app, clientList) {
        var item = grid.dataItem($(e.currentTarget).closest("tr"));
        for (var i = 0; i < clientList.length; i++) {
            if (clientList[i].name == item.name) {
                clientList.splice(i, 1);
            }
        }
        await api.put("DMS/" + app.Config.CRM.ClientFolder + "clientList.json", clientList);
        await api.destroy("DMS/" + app.Config.CRM.ClientFolder + item.name);
        grid.kendoObject.setDataSource({ data: clientList });
        grid.refresh();
    }
}",
