  {
    "Name": "FileVersionGrid",
    "Key": "DocumentManagement",
    "ResourceKey": "DocumentManagement",
    "Content": "",
    "Script": "FileVersionGrid = {
    init: async function (app, container, file, readOnly = false) {
        app = app || session.app;
        container = container || $(".component[name=FileVersionGrid]");

        api.addToMetaCache([
            {
                "Name": "Core",
                "Types": [
                    [meta[DocumentManagement/FileContent]],
                ]
            }
        ]);

        var datasource = model.getDatasource({
            endpoint: "DocumentManagement/FileContent",
            odataAppend:
                "?$select=Id,FileId,Description,Size,CreatedBy,CreatedOn,Version" +
                "&$filter=FileId eq " +
                file.Id
        });

        if (datasource.sort) {
            datasource.sort({ field: "CreatedOn", dir: "desc" });
        } else {
            datasource.sort = { field: "CreatedOn", dir: "desc" };
        }

        var grid = new GridWidget(
            container,
            datasource
        );

        FileVersionGrid.configureGrid(grid, file, readOnly, container);

        await grid.init();
    },

    configureGrid: function (grid, file, readOnly, container) {
        grid.groupable = false;
        grid.editable = false;
        grid.sortable = true;
        grid.columns = FileVersionGrid.getColumns(file);

        if (!readOnly) {
            FileVersionGrid.addCommands(grid);
        }

        grid.dataBound = function () {
            FileVersionGrid.bindCommands(grid, file, container);
        };
    },

    addCommands: function (grid) {
        grid.commands.push(
            {
                name: "download",
                icon: "k-i-download",
                text: "[resource_displayname[download]]"
            },
            {
                name: "delete",
                icon: "k-i-trash",
                text: "[resource_displayname[delete]]"
            }
        );
    },

    getColumns: function (file) {
        return [
            {
                field: "Version",
                width: 40,
                title: "#",
                sortable: false
            },
            {
                title: "",
                width: 46,
                sortable: false,
                template: function () {
                    var iconPath = window.DMSFormatting
                        ? DMSFormatting.iconPath(file.Name)
                        : "[api[root]]DMS/Content/DMSIcons/default.svg";

                    return (
                        '<img src="' +
                        iconPath +
                        '" style="height:36px;" onerror="this.src=\'[api[root]]DMS/Content/DMSIcons/default.svg\';" />'
                    );
                }
            },
            {
                title: "[resource_shortdisplayname[name]]",
                template: file.Name,
                sortable: false
            },
            {
                field: "Size",
                width: 80,
                title: "[resource_shortdisplayname[size]]",
                sortable: false
            },
            {
                field: "CreatedBy",
                width: 200,
                title: "[resource_shortdisplayname[createdBy]]",
                sortable: false
            },
            {
                field: "CreatedOn",
                width: 200,
                title: "[resource_shortdisplayname[createdOn]]",
                sortable: true,
                template:
                    "#=kendo.toString(new Date(CreatedOn), '" +
                    type.dateFormat +
                    " HH:mm:ss')#"
            }
        ];
    },

    bindCommands: function (grid, file, container) {
        $("[name=delete]", container)
            .off("click.fileVersionGrid")
            .on("click.fileVersionGrid", async function (event) {
                await FileVersionGrid.deleteFileVersion(event, grid, file);
            });

        $("[name=download]", container)
            .off("click.fileVersionGrid")
            .on("click.fileVersionGrid", function (event) {
                FileVersionGrid.downloadFileVersion(event, grid, file);
            });
    },

    downloadFileVersion: function (event, grid, file) {
        event.preventDefault();

        var fileVersion = FileVersionGrid.getSelectedVersion(event, grid);

        if (!fileVersion) {
            return;
        }

        window.location.assign(
            FileVersionGrid.getDownloadUrl(file, fileVersion.Version)
        );
    },

    getDownloadUrl: function (file, version) {
        return api.apiRoot +
            "DMS/" +
            file.Path +
            "?version=" +
            encodeURIComponent(version) +
            "&t=" +
            encodeURIComponent(session.token) +
            "&download";
    },

    deleteFileVersion: async function (event, grid, file) {
        event.preventDefault();

        var fileVersion = FileVersionGrid.getSelectedVersion(event, grid);

        if (!fileVersion) {
            return;
        }

        var confirmDialog = new ConfirmDialog({
            title: "[resource_displayname[areYouSure]]",
            question: "[resource_displayname[doyouwanttodeletethisfileversion]] [resource_displayname[cannotBeUndone]]",
