  {
    "Name": "FolderManagement",
    "Key": "DocumentManagement",
    "ResourceKey": "DocumentManagement",
    "Content": "",
    "Script": "FolderManagement = {
        init: async function (app, container, folder, readOnly, disablePaging = false) {
        app = app || session.app;
        container = container || $(".component[name=FolderManagement]");
        readOnly = readOnly || false;

        if (!folder) {
            return;
        }

        api.addToMetaCache([{
            Name: "DocumentManagement",
            Types: [
                [meta[DocumentManagement/Folder]],
                [meta[DocumentManagement/File]],
                [meta[DocumentManagement/FileContent]]
            ]
        }]);

        var shell = FolderManagement.renderShell(container);
        var fileList = $("[name=fileList]", shell);

        if (!fileList.length) {
            console.error("FolderManagement fileList container was not rendered.");
            return;
        }

        await FolderManagement.bindBreadcrumbNavigation(shell, app, folder, readOnly, disablePaging);

        var actions = await FolderManagement.loadActionComponents(shell, app);

        FolderManagement.bindToolbarActions(shell, app, folder, readOnly, disablePaging, actions.upload);
        FolderManagement.bindDesktopUploadDrop(shell, app, folder, readOnly, disablePaging, actions.upload);

        await FolderManagement.buildWidget(fileList, folder, readOnly, app, disablePaging);
    },

    renderShell: function (container) {
        var shell = $("[name=folderManagementShell]", container);

        if (!shell.length) {
            shell = $('<div name="folderManagementShell"></div>').appendTo(container);
        }

        shell.html([
            '<div class="folder-management">',
                '<div class="folder-main-toolbar">',
                    '<div class="folder-title-row">',
                        '<div class="folder-breadcrumb" name="folderPath"></div>',
                        '<div class="folder-title-actions">',
                            '<div class="folder-updated" name="folderUpdated"></div>',
                            '<button type="button" class="btn btn-sm btn-primary" name="manageFolder">',
                                '<span class="k-icon k-i-folder-more"></span>',
                                '[resource_displayname[managefolder]]',
                            '</button>',
                        '</div>',
                    '</div>',

                    '<div class="folder-action-row">',
                        '<div class="folder-actions mr-4">',
                            '<button type="button" class="btn btn-sm btn-primary" name="upload"><span class="k-icon k-i-upload"></span> [resource_displayname[upload]]</button>',
                            '<button type="button" class="btn btn-sm btn-primary" name="newFolder"><span class="k-icon k-i-plus"></span> [resource_displayname[newfolder]]</button>',
                        '</div>',

                        '<div class="context-toolbar context-toolbar-hidden" name="contextToolbar">',
                            '<strong name="selectedCount">0 items selected</strong>',
                            '<div class="context-toolbar-actions">',
                                '<button type="button" class="btn btn-sm btn-primary" name="contextMove"><span class="k-icon k-i-arrows-move"></span>[resource_displayname[move]]</button>',
                                '<button type="button" class="btn btn-sm btn-primary" name="contextRename"><span class="k-icon k-i-pencil"></span>[resource_displayname[rename]]</button>',
                                '<button type="button" class="btn btn-sm btn-primary" name="contextDownload"><span class="k-icon k-i-download"></span>[resource_displayname[download]]</button>',
                                '<button type="button" class="btn btn-sm btn-primary" name="contextDelete"><span class="k-icon k-i-trash"></span>[resource_displayname[delete]]</button>',
                            '</div>',
                        '</div>',

                        '<div class="folder-search">',
                            '<span class="k-icon k-i-search"></span>',
                            '<input type="text" class="form-control form-control-sm" name="fileSearch" placeholder="Search..." />',
                        '</div>',
                    '</div>',
                '</div>',

                '<div name="fileList" class="folder-file-list"></div>',
                '<div name="fileActionsHost" class="d-none"></div>',
                '<div name="folderActionsHost" class="d-none"></div>',
                '<div name="uploadActionsHost" class="d-none"></div>',
                '<div name="formattingHost" class="d-none"></div>',
            '</div>'
        ].join(""));

        return shell;
    },

    loadActionComponents: async function (shell, app) {
        await FolderManagement.loadDMSFormatting(shell, app);

        return {
            file: await FolderManagement.loadFileActions(shell, app),
            folder: await FolderManagement.loadFolderActions(shell, app),
            upload: await FolderManagement.loadUploadActions(shell, app)
        };
    },

    bindBreadcrumbNavigation: async function (shell, app, folder, readOnly, disablePaging) {
        var breadcrumb = $("[name=folderPath]", shell);

        if (!folder) {
            breadcrumb.empty();
            return;
        }

        var folders = (
            await api.get(
                "DocumentManagement/Folder?$filter=AppId eq " +
                app.Id +
                "&$orderby=Path asc&_=" +
                Date.now()
            )
        ).value || [];

        FolderManagement.renderBreadcrumb(
            breadcrumb,
            folders,
            folder,
            app,
            readOnly,
            disablePaging
        );
    },

    renderBreadcrumb: function (breadcrumb, folders, currentFolder, app, readOnly, disablePaging) {
        breadcrumb.empty();

        if (!currentFolder) {
            return;
        }

        var pathParts = (currentFolder.Path || currentFolder.Name || "")
            .split("/")
            .filter(Boolean);

        if (!pathParts.length) {
            breadcrumb.text(currentFolder.Name || "");
            return;
        }

        var foldersByPath = {};
        var cumulativePath = "";

        for (var i = 0; i < folders.length; i++) {
            foldersByPath[FolderManagement.normalisePath(folders[i].Path)] = folders[i];
        }

        for (var j = 0; j < pathParts.length; j++) {
            cumulativePath = cumulativePath
                ? cumulativePath + "/" + pathParts[j]
                : pathParts[j];

            var matchedFolder = foldersByPath[
                FolderManagement.normalisePath(cumulativePath)
            ];

            if (j > 0) {
                $("<span />")
                    .addClass("folder-breadcrumb-separator")
                    .text("/")
                    .appendTo(breadcrumb);
            }

            FolderManagement.buildBreadcrumbSegment(
                matchedFolder,
                pathParts[j],
                j === pathParts.length - 1,
                app,
                readOnly,
                disablePaging
            ).appendTo(breadcrumb);
        }
    },

    buildBreadcrumbSegment: function (folder, fallbackText, isCurrent, app, readOnly, disablePaging) {
        var segment = $("<a />")
            .attr("href", "#")
            .addClass("folder-breadcrumb-link")
            .toggleClass("folder-breadcrumb-current", isCurrent)
            .text(folder ? folder.Name : fallbackText);

        if (!folder || isCurrent) {
            return segment
                .toggleClass("folder-breadcrumb-missing", !folder)
                .on("click.folderBreadcrumb", function (event) {
                    event.preventDefault();
                });
        }

        segment
            .data("folder", folder)
            .off("click.folderBreadcrumb")
            .on("click.folderBreadcrumb", function (event) {
                event.preventDefault();

                FolderManagement.navigateToBreadcrumbFolder(
                    app,
                    $(this).data("folder"),
                    readOnly,
                    disablePaging
                );
            });

        return segment;
    },

    navigateToBreadcrumbFolder: async function (app, folder, readOnly, disablePaging) {
        await FolderManagement.reloadFolderView(app, folder, readOnly, disablePaging);

        FolderManagement.selectFolderInTree(folder);
    },

    selectFolderInTree: function (folder) {
        var treeElement = $(".component[name=DocumentManagement] [name=treeRoot]");
        var treeView = treeElement.data("kendoTreeView");

        if (!treeView || !folder) {
            return;
        }

        var node = FolderManagement.findTreeNodeByFolderId(treeView.dataSource.view(), folder.Id );

        if (!node) {
            return;
        }

        var treeNode = treeView.findByUid(node.uid);

        if (!treeNode || !treeNode.length) {
            return;
        }

        treeView.select(treeNode);

        if (window.DocumentManagement && DocumentManagement.highlightSelectedPath) {
            DocumentManagement.highlightSelectedPath({ kendoObject: treeView }, treeNode);
        }

        if (window.DocumentManagement && DocumentManagement.updateTreeFolderIcons) {
            DocumentManagement.updateTreeFolderIcons({ kendoObject: treeView });
        }
    },

    findTreeNodeByFolderId: function (nodes, folderId) {
        for (var i = 0; i < nodes.length; i++) {
            if (nodes[i].id === folderId) {
                return nodes[i];
            }

            var childMatch = FolderManagement.findTreeNodeByFolderId(nodes[i].items || [], folderId);

            if (childMatch) {
                return childMatch;
            }
        }

        return null;
    },

    normalisePath: function (path) {
        return (path || "")
            .replace(/^\/+|\/+$/g, "")
            .toLowerCase();
    },

    bindToolbarActions: function (shell, app, folder, readOnly, disablePaging, uploadActions) {
        FolderManagement.bindFolderAction(shell, app, "newFolder", function (actions) {
            actions.openCreate(folder, function (createdFolder) {
                return FolderManagement.afterFolderCreate(app, folder, readOnly, disablePaging, createdFolder);
            });
        });

        FolderManagement.bindUploadAction( shell, app, folder, readOnly, disablePaging, uploadActions);

        FolderManagement.bindFolderAction(shell, app, "manageFolder", function (actions) {
            actions.openManage(folder, function () {
                return FolderManagement.afterFolderManage(app, folder, readOnly, disablePaging);
            });
        });
    },

    bindUploadAction: function (shell, app, folder, readOnly, disablePaging, uploadActions) {
        $("[name=upload]", shell)
            .off("click.folderManagement")
            .on("click.folderManagement", function (event) {
                event.preventDefault();

                if (!uploadActions || !uploadActions.openUniversalUpload) {
                    console.error("UploadActions was not loaded for upload button.");
                    return;
                }

                uploadActions.openUniversalUpload(
                    folder,
                    function (createdFolder) {
                        return FolderManagement.afterUploadComplete(app, folder, readOnly, disablePaging, createdFolder);
                    }
                );
            });
    },

    bindFolderAction: function (shell, app, buttonName, handler) {
        $('[name="' + buttonName + '"]', shell)
            .off("click.folderManagement")
            .on("click.folderManagement", async function (event) {
                event.preventDefault();

                await FolderManagement.loadFolderActions(shell, app, handler);
            });
    },

    reloadCurrentFolder: function (app, shell, folder, readOnly, disablePaging) {
        return FolderManagement.init(app,shell.closest(".component[name=FolderManagement]"),folder,readOnly,disablePaging);
    },

    refreshDocumentManagement: function (app) {
        return DocumentManagement.init(
            app,
            $(".component[name=DocumentManagement]")
        );
    },

    loadFolderActions: function (shell, app, callback) {
        return FolderManagement.loadActions(shell, app, "folderActionsHost", "FolderActions", callback);
    },

    loadFileActions: function (shell, app, callback) {
        return FolderManagement.loadActions(shell, app, "fileActionsHost", "FileActions", callback);
    },

    loadUploadActions: function (shell, app, callback) {
        return FolderManagement.loadActions(shell, app, "uploadActionsHost", "UploadActions", callback);
    },

    loadDMSFormatting: function (shell, app, callback) {
        return FolderManagement.loadActions(shell, app, "formattingHost", "DMSFormatting", callback);
    },
    
    loadActions: async function (shell, app, hostName, componentName, callback) {
        var cacheKey = componentName + "Instance";

        if (FolderManagement[cacheKey]) {
            if (callback) {
                await callback(FolderManagement[cacheKey]);
            }

            return FolderManagement[cacheKey];
        }

        var host = $('[name="' + hostName + '"]', shell);
        var loadedComponent = null;

        await loadComponent(host, componentName, async function (component) {
            component = component || window[componentName];

            if (!component || !component.init) {
                console.error(componentName + " failed to load.");
                return;
            }

            await component.init(app, host);
            loadedComponent = component;
            FolderManagement[cacheKey] = component;

            if (callback) {
                await callback(component);
            }
        });

        return loadedComponent;
    },

    buildWidget: async function (element, folder, readOnly, app, disablePaging = false) {
            var selectionKeys = FolderManagement.bindSelectionKeys();

            var datasource = await model.getDatasource({
                endpoint: "DocumentManagement/File",
                odataAppend:
                    "?$filter=FolderId eq " +
                    folder.Id +
                    "&$expand=Contents($select=CreatedOn;$orderBy=CreatedOn desc;$top=1)"
            });

            if (datasource.sort) {
                datasource.sort({ field: "Name", dir: "asc" });
            } else {
                datasource.sort = { field: "Name", dir: "asc" };
            }

            var folderGrid = new GridWidget(
                element,
                datasource
            );

            folderGrid.app = app;
            folderGrid.folder = folder;
            folderGrid.groupable = false;
            folderGrid.editable = false;
            folderGrid.scrollable = true;
            folderGrid.sortable = true;
            folderGrid.filterable = !disablePaging;
            folderGrid.pageable = disablePaging ? false : { pageSizes: false, refresh: true };
            folderGrid.columns = FolderManagement.getColumns();

        folderGrid.dataBound = function () {
            FolderManagement.bindGridSelection(folderGrid, selectionKeys);
            FolderManagement.bindFileDrag(folderGrid);
            FolderManagement.updateContextToolbar(folderGrid);
        };

        folderGrid.detailTemplate = kendo.template("<div name='fileVersionGrid'></div>");

        folderGrid.detailExpand = async function (event) {
            var detailHost = $("[name=fileVersionGrid]", event.detailRow);

            if (!detailHost.length) {
                return;
            }

            if (detailHost.data("loadingVersions")) {
                return;
            }

            detailHost
                .data("loadingVersions", true)
                .empty();

            try {
                await FileActions.expandVersions(event, app, folderGrid, readOnly);
            } finally {
                detailHost.data("loadingVersions", false);
            }
        };

        await folderGrid.init();

        FolderManagement.bindFileSearch(folderGrid);
        FolderManagement.bindContextToolbar(folderGrid);
        FolderManagement.bindGridEvents(folderGrid, readOnly);
        FolderManagement.updateContextToolbar(folderGrid);
        FolderManagement.resizeGrid(folderGrid);
    },

    bindSelectionKeys: function () {
        var keys = {
            shift: false,
            ctrl: false
        };

        $(window)
            .off(".folderManagementSelection")
            .on("keydown.folderManagementSelection", function (event) {
                keys.shift = keys.shift || event.which === 16;
                keys.ctrl = keys.ctrl || event.which === 17;
            })
            .on("keyup.folderManagementSelection", function (event) {
                if (event.which === 16) {
                    keys.shift = false;
                }

                if (event.which === 17) {
                    keys.ctrl = false;
                }
            });

        return keys;
    },

    getColumns: function () {
        return [
            { selectable: true, width: 32 },
            {
                title: "",
                width: 46,
                template: function (dataItem) {
                    return (
                        '<img src="' +
                        DMSFormatting.iconPath(dataItem.Name) +
                        '" style="height:36px;" onerror="this.src=\'/icons/default.svg\';" />'
                    );
                }
            },
            {
                field: "Name",
                title: "[resource_shortdisplayname[name]]"
            },
            {
                field: "Size",
                width: 100,
                filterable: false,
                title: "[resource_shortdisplayname[size]]"
            },
            {
                field: "CreatedBy",
                title: "[resource_shortdisplayname[createdby]]",
                editable: false,
                width: "[theme[columns.small]]"
            },
            {
                field: "Contents[0].CreatedOn",
                title: "[resource_shortdisplayname[lastupdated]]",
                editable: false,
                template:
                    "#: Contents && Contents.length ? kendo.toString(new Date(Contents[0].CreatedOn), '" +
                    "dd-MM-yyyy HH:mm:ss') : '' #",
                width: "[theme[columns.medium]]"
            }
        ];
    },

    bindGridSelection: function (grid, selectionKeys) {
        grid.gridElement
            .off("click.fileSelection", "tr.k-master-row")
            .on("click.fileSelection", "tr.k-master-row", function (event) {
                if (selectionKeys.shift) {
                    FolderManagement.shiftClick(event, grid);
                }

                if (selectionKeys.ctrl) {
                    FolderManagement.ctrlClick(event, grid);
                }
            });
    },

    bindGridEvents: function (grid, readOnly) {
        grid.gridElement
            .off("contextmenu.fileActions")
            .on("contextmenu.fileActions", "tr.k-master-row", function (event) {
                event.preventDefault();
            })
            .off("click.contextToolbar")
            .on("click.contextToolbar", "tr.k-master-row, input[type=checkbox]", function () {
                setTimeout(function () {
                    FolderManagement.updateContextToolbar(grid);
                }, 0);
            });
    },

    bindContextToolbar: function (grid) {
        var toolbar = grid.gridElement
            .closest(".folder-management")
            .find("[name=contextToolbar]");

        $("[name=contextMove]", toolbar)
            .off("click.folderManagement")
            .on("click.folderManagement", async function (event) {
                event.preventDefault();

                await FolderManagement.loadFolderActions(
                    grid.gridElement.closest(".folder-management"),
                    grid.app,
                    function (actions) {
                        actions.openMove(grid, function () {
                            return FolderManagement.afterFileAction(grid);
                        });
                    }
                );
            });

        $("[name=contextRename]", toolbar)
            .off("click.folderManagement")
            .on("click.folderManagement", function (event) {
                FileActions.openRenameSelected(event, grid, function () {
                    return FolderManagement.afterFileAction(grid);
                });
            });

        $("[name=contextDownload]", toolbar)
            .off("click.folderManagement")
            .on("click.folderManagement", function (event) {
                FileActions.downloadSelected(event, grid);
            });

        $("[name=contextDelete]", toolbar)
            .off("click.folderManagement")
            .on("click.folderManagement", function (event) {
                FileActions.deleteSelected(event, grid, function () {
                    return FolderManagement.afterFileAction(grid);
                });
            });
    },

    afterFileAction: async function (grid) {
        await grid.refresh();
        FolderManagement.updateContextToolbar(grid);
    },

    updateContextToolbar: function (grid) {
        var count = grid.select().length;
        var toolbar = grid.gridElement
            .closest(".folder-management")
            .find("[name=contextToolbar]");

        if (!toolbar.length) {
            return;
        }

        toolbar.toggleClass("context-toolbar-hidden", count === 0);

        if (count) {
            $("[name=selectedCount]", toolbar).text(
                count +
                " " +
                (count === 1 ? "item" : "items") +
                " selected"
            );
        }

        FolderManagement.resizeGrid(grid);
    },

    bindFileSearch: function (grid) {
        grid.gridElement
            .closest(".folder-management")
            .find("[name=fileSearch]")
            .off("input.fileSearch")
            .on(
                "input.fileSearch",
                FolderManagement.debounce(function () {
                    FolderManagement.searchFiles(grid, $(this).val());
                }, 250)
            );
    },

    searchFiles: function (grid, searchTerm) {
        var value = (searchTerm || "").trim();

        grid.kendoObject.dataSource.filter(
            value
                ? {
                    logic: "or",
                    filters: [
                        {
                            field: "Name",
                            operator: "contains",
                            value: value,
                            ignoreCase: true
                        },
                        {
                            field: "CreatedBy",
                            operator: "contains",
                            value: value,
                            ignoreCase: true
                        }
                    ]
                }
                : {}
        );
    },

    clearSelection: function (event, grid) {
        event.preventDefault();

        grid.clearSelection();
        FolderManagement.updateContextToolbar(grid);
    },

    ctrlClick: function (event, grid) {
        grid.kendoObject.select($(event.currentTarget).closest("tr"));
        FolderManagement.updateContextToolbar(grid);
    },

    shiftClick: function (event, grid) {
        var selectedRows = $("tr.k-state-selected", grid.gridElement);

        if (!selectedRows.length) {
            return;
        }

        var selectedIndex = selectedRows.index();
        var currentIndex = $(event.currentTarget).closest("tr").index();
        var children = selectedRows.parent().children();
        var start = Math.min(selectedIndex, currentIndex);
        var end = Math.max(selectedIndex, currentIndex);

        grid.kendoObject.clearSelection();

        for (var i = start; i <= end; i++) {
            grid.kendoObject.select(children[i]);
        }

        FolderManagement.updateContextToolbar(grid);
    },

    resizeGrid: function (grid) {
        setTimeout(function () {
            if (grid.kendoObject && grid.kendoObject.resize) {
                grid.kendoObject.resize();
            }
        }, 0);
    },

    debounce: function (callback, delay) {
        var timer;

        return function () {
            var context = this;
            var args = arguments;

            clearTimeout(timer);

            timer = setTimeout(function () {
                callback.apply(context, args);
            }, delay);
        };
    },

    bindDesktopUploadDrop: function (shell, app, folder, readOnly, disablePaging, uploadActions) {
        shell
            .off("dragenter.folderUpload dragover.folderUpload dragleave.folderUpload drop.folderUpload")
            .on("dragenter.folderUpload dragover.folderUpload", function (event) {
                if (!FolderManagement.isDesktopFileDrop(event.originalEvent)) {
                    return;
                }

                event.preventDefault();
                event.stopPropagation();

                event.originalEvent.dataTransfer.dropEffect = "copy";
                shell.find(".folder-management").addClass("folder-upload-drag-active");
            })
            .on("dragleave.folderUpload", function (event) {
                if ($(event.relatedTarget).closest(shell).length) {
                    return;
                }

                shell.find(".folder-management").removeClass("folder-upload-drag-active");
            })
            .on("drop.folderUpload", async function (event) {
                if (!FolderManagement.isDesktopFileDrop(event.originalEvent)) {
                    return;
                }

                event.preventDefault();
                event.stopPropagation();

                shell.find(".folder-management").removeClass("folder-upload-drag-active");

                if (!uploadActions || !uploadActions.getDroppedUploadItems) {
                    console.error("UploadActions was not loaded for upload drop.");
                    return;
                }

                var uploadItems = await uploadActions.getDroppedUploadItems(event.originalEvent);

                if (!uploadItems.length) {
                    return;
                }

                uploadActions.openUniversalUpload(
                    folder,
                    function (createdFolder) {
                        return FolderManagement.afterUploadComplete(app, folder, readOnly, disablePaging, createdFolder);
                    },
                    uploadItems
                );
            });
    },

    isDesktopFileDrop: function (event) {
        return !!(
            event &&
            event.dataTransfer &&
            event.dataTransfer.types &&
            Array.prototype.indexOf.call(event.dataTransfer.types, "Files") >= 0
        );
    },

    bindFileDrag: function (grid) {
        grid.gridElement
            .find("tr.k-master-row")
            .attr("draggable", true);

        grid.gridElement
            .off("dragstart.fileMove dragend.fileMove", "tr.k-master-row")
            .on("dragstart.fileMove", "tr.k-master-row", function (event) {
                var row = $(this);
                var draggedFile = grid.dataItem
                    ? grid.dataItem(row)
                    : grid.kendoObject.dataItem(row);

                var selectedFiles = FolderManagement.rowIsSelected(row)
                    ? grid.select()
                    : [draggedFile];

                selectedFiles = selectedFiles.filter(function (file) {
                    return !!file;
                });

                if (!selectedFiles.length) {
                    return FolderManagement.cancelDrag(event);
                }

                event.originalEvent.dataTransfer.effectAllowed = "move";
                event.originalEvent.dataTransfer.setData(
                    "application/x-dms-files",
                    JSON.stringify({
                        files: selectedFiles.map(function (file) {
                            return {
                                Id: file.Id,
                                Name: file.Name,
                                Path: file.Path,
                                FolderId: file.FolderId
                            };
                        })
                    })
                );

                event.originalEvent.dataTransfer.setData(
                    "text/plain",
                    selectedFiles.length +
                        " " +
                        (selectedFiles.length === 1 ? "file" : "files")
                );

                grid.gridElement.addClass("dms-file-dragging");
            })
            .on("dragend.fileMove", "tr.k-master-row", function () {
                grid.gridElement.removeClass("dms-file-dragging");
            });
    },

    rowIsSelected: function (row) {
        return row.hasClass("k-selected") ||
            row.hasClass("k-state-selected");
    },

    cancelDrag: function (event) {
        event.preventDefault();
        event.stopPropagation();

        if (event.originalEvent && event.originalEvent.dataTransfer) {
            event.originalEvent.dataTransfer.effectAllowed = "none";
        }

        return false;
    },

    reloadFolderView: async function (app, folder, readOnly, disablePaging) {
        if (!folder) {
            return;
        }

        var container = $(".component[name=FolderManagement]");
        var shell = $("[name=folderManagementShell]", container);
        var fileList = $("[name=fileList]", shell);

        if (!shell.length || !fileList.length) {
            return FolderManagement.init(app, container, folder, readOnly, disablePaging);
        }

        await FolderManagement.bindBreadcrumbNavigation(shell, app, folder, readOnly, disablePaging);

        var actions = await FolderManagement.loadActionComponents(shell, app);

        FolderManagement.bindToolbarActions(shell, app, folder, readOnly, disablePaging, actions.upload);
        FolderManagement.bindDesktopUploadDrop(shell, app, folder, readOnly, disablePaging, actions.upload);

        fileList.empty();

        await FolderManagement.buildWidget(fileList, folder, readOnly, app, disablePaging);
    },

    afterUploadComplete: async function (app, currentFolder, readOnly, disablePaging, createdFolder) {
        var folderToLoad = currentFolder;

        if (createdFolder && createdFolder.Path) {
            var matchedFolder = await FolderManagement.getFolderByPath(app, createdFolder.Path);

            if (matchedFolder) {
                folderToLoad = matchedFolder;
            }
        }

        await DocumentManagement.refreshTreeAfterFolderChange(app, folderToLoad.Id);

        await FolderManagement.reloadFolderView(app, folderToLoad, readOnly, disablePaging);

        FolderManagement.selectFolderInTree(folderToLoad);
    },

    afterFolderCreate: async function (app, currentFolder, readOnly, disablePaging, createdFolder) {
        var folderToLoad = createdFolder || currentFolder;

        if (folderToLoad && folderToLoad.Path) {
            var matchedFolder = await FolderManagement.getFolderByPath(app, folderToLoad.Path);

            if (matchedFolder) {
                folderToLoad = matchedFolder;
            }
        }

        await DocumentManagement.refreshTreeAfterFolderChange(app, folderToLoad.Id);

        await FolderManagement.reloadFolderView(app, folderToLoad, readOnly, disablePaging);

        FolderManagement.selectFolderInTree(folderToLoad);
    },

    afterFolderManage: async function (app, folder, readOnly, disablePaging) {
        var latestFolder = await api.get("DocumentManagement/Folder(" + folder.Id + ")");

        await DocumentManagement.refreshTreeAfterFolderChange(app, latestFolder.Id);

        await FolderManagement.reloadFolderView(app, latestFolder, readOnly, disablePaging);

        FolderManagement.selectFolderInTree(latestFolder);
    },

    getFolderByPath: async function (app, path) {
        var result = await api.get(
            "DocumentManagement/Folder?$filter=AppId eq " +
            app.Id +
            " and Path eq '" +
            path.replace(/'/g, "''") +
            "'&_=" +
            Date.now()
        );

        return result && result.value && result.value.length
            ? result.value[0]
            : null;
    },
