    "Script": "FormManagement = {
    init: function (app) {
		if(!app) { app = session.app; }
        var root = $(".component[name=Forms]");
        var config = { 
			endpoint: "ContentManagement/Form", 
			filter: {
				logic: "and",
				filters: [
					{ field: "AppId", operator: "eq", value: app.Id }
				]
			} 
		};

		model.getDatasource(config, function (ds) {
			var grid = $("[name=grid]", root).kendoGrid({
				dataSource: ds,
				editable: true,
				sortable: true,
				filterable: true,
				pageable: {
					refresh: true,
					pageSizes: true,
					buttonCount: 5
				},
