    "Script": "HistoryList = {
    init: async function (app, container, historyDMSPath) {
        app = app || session.app;
        container = container || $(".component[name=HistoryList]");
        var history = await api.get(historyDMSPath);
        var historyGrid = new GridWidget($("[name=historyGrid]",container), {data: history});
        historyGrid.toolbar ="<button name='add'><span class='k-icon k-i-plus'></span>[resource_displayname[add]]</button><button name='save'><span class='k-icon k-i-save'></span>[resource_displayname[save]]</button>";
        historyGrid.groupable = false;
        historyGrid.pageable = false;
        historyGrid.columns = [
            { field: "created", title: "[resource_displayname[created]]", format: "{0:" + type.dateFormat + "}", type: "date", width: 160, title: "[resource_displayname[created]]" },
            { field: "content", title: "[resource_displayname[content]]", title: "[resource_displayname[content]]" }
        ];
        historyGrid.commands.push({ name: "edit", icon: "k-i-pencil", text: "[resource_displayname[edit]]" });
        historyGrid.commands.push({ name: "remove", icon: "k-i-trash", text: "[resource_displayname[delete]]" });
        historyGrid.dataBound = function () {
            $("[name=remove]", historyGrid.gridElement).on("click", async function (e) { 
                var item = historyGrid.kendoObject.dataItem($(e.currentTarget).closest("tr"));
                await HistoryList.removeHistory(e, historyGrid, item); 
            });
            $("[name=edit]", historyGrid.gridElement).on("click", async function (e) {
                var item = historyGrid.kendoObject.dataItem($(e.currentTarget).closest("tr"));
                await HistoryList.editHistory(item, historyGrid);
            });
        };
        await historyGrid.init();
        $("[name=add]", historyGrid.gridElement).on("click", async function (e) { await HistoryList.addHistory(e, historyGrid); });
        $("[name=save]", historyGrid.gridElement).on("click", async function (e) { await HistoryList.save( historyGrid, historyDMSPath); });
    },

    save: async function (historyGrid, historyDMSPath) {
        await api.put(historyDMSPath, historyGrid.kendoObject.dataSource.data()).then(() => {
            notification.success("[resource_displayname[saved]]");
            historyGrid.kendoObject.refresh();
        }).catch((err) => { error(err); });
    },

    addHistory: function (e, historyGrid) {
        var addHistoryDialog = new Dialog({ title: "[resource_displayname[AddHistory]]", width: 700, height: "auto" });
        addHistoryDialog.template = $("[name=addHistoryDialog]").html();
        addHistoryDialog.events.confirm = async function () {
            var model = { created: (new Date()).toISOString(), content: $("[name=history]", addHistoryDialog.element).data("kendoEditor").value() }
            historyGrid.kendoObject.dataSource.insert(0, model);
            historyGrid.kendoObject.refresh();
            addHistoryDialog.events.close();
        };
        addHistoryDialog.init(() => {
            $("[name=history]", addHistoryDialog.element).kendoEditor();
        });
    },

    editHistory: async function (historyEntry, historyGrid) {
        var editHistoryDialog = new Dialog({ title: "[resource_displayname[edithistory]]", width: 700, height: "auto" });
        editHistoryDialog.template = $("[name=editHistoryDialog]").html();
        editHistoryDialog.events.confirm = async function () {
            historyEntry.content = $("[name=editHistory]", editHistoryDialog.element).data("kendoEditor").value();
            historyGrid.kendoObject.refresh();
            editHistoryDialog.events.close();
        };
        editHistoryDialog.init(() => {
            $("[name=editHistory]", editHistoryDialog.element).kendoEditor().data("kendoEditor").value(historyEntry.content);
        });
    },

    removeHistory: async function (e, historyGrid, historyEntry) {
        historyGrid.kendoObject.dataSource.remove(historyEntry);
    }
}",
