    "Name": "TenantActivity",
    "Key": "Security",
    "ResourceKey": "Security",
    "Script": "TenantActivity = {
    init: async function(app, container, tenant) {
        app = app || session.app;
        container = container || $(".component[name=TenantActivity]");
        
        tenant.apps = (await api.get(`ContentManagement/App?$filter=TenantId eq '${tenant.Id}'`))
            .value;

        await TenantActivity.initGrid(container, tenant);
    },

    initGrid: async function(container, tenant) {
        api.addToMetaCache([
            {
                "Name": "Security",
                "Types": [
                    [meta[Security/UserEvent]]
                ]
            }
        ]);

        var dsConfig = {
            endpoint: "Security/UserEvent",
            odataAppend: `?$filter=TenantId eq '${tenant.Id}'`
        };

        var ds = await model.getDatasource(dsConfig);
        var grid = new GridWidget($("[name=grid]", container), ds);
        grid.searchable = false;
        grid.filterable = true;
        grid.editable = false;
        grid.exports = false;

        //tenantGrid.detailTemplate = $("[name=activityDetails]", container).first().html();

        grid.columns = [
            { 
                field: "SessionId", 
                title: "SessionId" 
            },
            { 
                field: "CreatedBy", 
                title: "CreatedBy" 
            },
            { 
                field: "CreatedOn", 
                title: "CreatedOn",
                format: "{0:" + type.dateFormat + " H:mm:ss}", 
                type: "date",
                width: "[theme[columns.small]]"
            },
            { 
                field: "EventName", 
                title: "EventName",
                filterable: { multi: true, search: true }
            },
            { 
                field: "Value", 
                title: "Url" 
            },
        ];

        grid.toolbar = $('[name=activity-toolbar]', container).html();

        await grid.init();

        $("button[name=genActivityReport]", container)
            .on("click", (e) => TenantActivity.openGenerationDialog(tenant));
    },

    openGenerationDialog: function(tenant) {
        var fromMonth = (new Date().getMonth() + 1).toString().padStart('0', 2);
        var toMonth = (new Date().getMonth() + 1).toString().padStart('0', 2);

        var model = kendo.observable({ 
            tenant: tenant,
            appId: tenant.apps[0].Id,
            fromYear: "2025",
            fromMonth: fromMonth,
            toYear: "2025",
            toMonth: toMonth,
            start: null,
            end: null
        });

        var dialogConfig = { 
            name: "activityReportGenerator",
            title: "[resource_displayname[generateactivityreport]]", 
            width: 620, 
            height: "auto",
            template: $("script[name=activity-report-dialog]")
                .first()
                .html()
        };

        var d = new Dialog(dialogConfig);
        d.events.generate = () => { 
            d.events.close();
            TenantActivity.generateReport(model);
        };

        d.init(() => {
            TenantActivity.setupReportGeneration(d.element, model);
            kendo.bind(d.element, model);
        });
    },

    generateReport: async function(reportParams) {
        reportParams.start = reportParams.fromYear + "-" + reportParams.fromMonth + "-01";
        
        var end = reportParams.toYear + "-" + reportParams.toMonth + "-01";
        end = new Date(end);
        end.setMonth(end.getMonth() + 1);
        end.setDate(0);
        reportParams.end = end.toISOString().split('T')[0];

        reportParams.Data = await TenantActivity.getReportData(reportParams);
        var reportUrl = `ContentManagement/Template/Render?appId=${session.app.Id}&name=Test&culture=${session.culture}`;
        var report = await api.post(reportUrl, reportParams);

        var dialogConfig = { 
            name: "activityReport",
            title: "[resource_displayname[activityreport]]", 
            width: 1200, 
            height: 800,
            template: `
                <div class="k-toolbar">
                    <div class="btn-group btn-group-sm">
                        <button class="btn btn-primary" name="downloadReport">
                            <span class="k-icon k-svg-icon k-svg-i-save" aria-hidden="true"></span>
                            Download This Report
                        </button>
                    </div>
                </div>
                <div style="height: 730px; width: 1200px;" name="report"></div>`
        };

        var d = new Dialog(dialogConfig);
        d.events.downloadReport = () => TenantActivity.downloadReport(report);
        d.init();

        const iframe = document.createElement('iframe');
        iframe.srcdoc = report;
        iframe.style.width = "100%";
        iframe.style.height = "100%";
        iframe.style.border = "none";
        $("[name=report]", d.element).append(iframe);
    },

    setupReportGeneration: function(container, model) {
       var apps = [];
       model.tenant.apps.map(a => apps.push({ Id: a.Id, Name: `${a.Name} (${a.Domain})`}))

        $("[name=appId]", container)
            .kendoDropDownList({
                dataSource: apps,
                dataTextField: "Name",
			    dataValueField: "Id"
            }).data("kendoDropDownList");

        $("select[name=fromMonth]", container)
            .kendoDropDownList();

        $("select[name=fromYear]", container)
            .kendoDropDownList();

        $("select[name=toMonth]", container)
            .kendoDropDownList();

        $("select[name=toYear]", container)
            .kendoDropDownList();
    },

    getReportData: async function(reportParams) {
        var tenant = reportParams.tenant.Id;
        var filter = "$filter=TenantId eq '" + tenant + "' and Name eq 'User Activity (Daily)' and CreatedOn ge " + reportParams.start + " and CreatedOn le " + reportParams.end;

        var analytics = (await api.get(`Security/TenantAnalysis?${filter}&$format=json&$orderby=CreatedOn desc&$count=true`))
            .value
            .map((entry) => {
                return {
                    date: entry.CreatedOn.split('T')[0],
                    data: JSON.parse(entry.Value)
                };
            });

        var data = [];
        
        for(var i in analytics) {
            var entry = analytics[i];
            
            data.push({
                date: entry.date,
                users: entry.data.Users,
                apiCalls: entry.data.ApiCalls,
                pages: entry.data.Pages
            });
        }

        var users = [];
        var sessions = [];
        var pageHits = [];
        var apiCalls = [];

        var userIds = new Set();

        for(var i in data) {
            var row = data[i];
            
            for(var u in row.users) {
                var user = row.users[u];

                if (!userIds.has(user.User.Id)) {
                    users.push({ Id: user.User.Id, DisplayName: user.User.UserDisplayName, Email: user.User.UserEmail });
                    userIds.add(user.User.Id);
                }

                sessions.push({ Date: row.date, DisplayName: user.User.UserDisplayName, Email: user.User.UserEmail, SessionCount: user.Sessions, PageHits: user.PageRequests, ApiCalls: user.ApiRequests });
            }
            
            for(var p in row.pages) {
                var page = row.pages[p];
                pageHits.push({ Date: row.date, Page: page.Page, Hits: page.Hits, Sessions: page.Sessions });
            }
            
            for(var a in row.apiCalls) {
                var apiCall = row.apiCalls[a];
                apiCalls.push({ Date: row.date, Endpoint: apiCall.Endpoint, Hits: apiCall.Hits, Sessions: apiCall.Sessions });
            }
        } 

        return {
            Users: users,
            Sessions: sessions,
            PageHits: pageHits,
            ApiCalls: apiCalls
        };
    },

    downloadReport: async function(report) {
        const response = await fetch('Api/ContentManagement/Template/HtmlToPdf?name=Activity Report', {
            method: 'POST',
            headers: { 'Content-Type': 'text/plain' },
            body: report,
        });

        const pdfBlob = await response.blob();
        const url = window.URL.createObjectURL(pdfBlob);
        const link = document.createElement('a');
        link.href = url;
        link.download = 'Activity Report.pdf';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link); 
        window.URL.revokeObjectURL(url); 
    }
}",
